import {createHudContrastControl} from './hud-appearance.js';
import {bindViewButton,mountViewControl} from './view-options.js?v=3.70.0';
// Shared screen pause menu. A click requesting WebXR keeps its user activation.
export function createPauseMenu({title='PINK WARS',onPause=()=>{},onResume=()=>{},onVR=()=>{},onHome=()=>location.assign('./index.html'),canOpen=()=>true,vrLabel='Passer en VR',settingsSelectors=[],view=null}={}){
 const dialog=document.createElement('dialog');dialog.className='fracture-pause';dialog.setAttribute('aria-label','Menu pause');
 dialog.innerHTML='<p class="fracture-kicker"></p><h2>En pause.</h2><p class="fracture-description">Le monde attend votre retour.</p><div class="fracture-choices"><button data-pause-action="resume" class="fracture-primary">Reprendre <span>→</span></button><button data-pause-action="settings">Réglages</button><button data-pause-action="vr"></button><button data-pause-action="home">Retour à l’accueil</button></div><p class="fracture-status" role="status"></p>';
 dialog.querySelector('.fracture-kicker').textContent=title;dialog.querySelector('[data-pause-action="vr"]').textContent=vrLabel;
 const pauseViewControl=view?bindViewButton(document.createElement('button'),view):null;
 if(pauseViewControl){pauseViewControl.button.type='button';pauseViewControl.button.dataset.pauseView='';dialog.querySelector('[data-pause-action="resume"]').after(pauseViewControl.button);}
 const settings=document.createElement('section');settings.className='fracture-settings';settings.hidden=true;settings.setAttribute('aria-label','Réglages de la partie');settings.append(createHudContrastControl());
 const settingsContent=document.createElement('div');settingsContent.className='fracture-settings-content';settings.append(settingsContent);
 const viewControl=view?mountViewControl(settingsContent,view):null;
 const back=document.createElement('button');back.type='button';back.className='fracture-settings-back';back.textContent='Retour à la pause';settings.append(back);dialog.append(settings);let settingsOpen=false;const moved=[];
 function showSettings(value){viewControl?.refresh();settingsOpen=!!value;settings.hidden=!settingsOpen;dialog.querySelector('.fracture-choices').hidden=settingsOpen;dialog.querySelector('h2').textContent=settingsOpen?'Réglages.':'En pause.';if(settingsOpen&&!moved.length)for(const selector of settingsSelectors){const node=document.querySelector(selector);if(node){moved.push({node,parent:node.parentNode,next:node.nextSibling});settingsContent.append(node);}}(settingsOpen?back:dialog.querySelector('[data-pause-action=settings]')).focus();}
 back.onclick=()=>showSettings(false);
 const actions=document.createElement('nav');actions.className='fracture-session-actions';actions.setAttribute('aria-label','Pause et réalité virtuelle');
 actions.innerHTML='<button data-session="vr" aria-label="Passer en VR" title="Passer en VR"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16l2 9-3 2h-4l-3-3-3 3H5l-3-2L4 7Z"/><circle cx="7" cy="12" r="2"/><circle cx="17" cy="12" r="2"/></svg><span>VR</span></button><button data-session="pause" aria-label="Menu pause" title="Menu pause"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5v14m8-14v14"/></svg></button>';
 document.body.append(actions,dialog);let open=false,padFrame=0,previous=[];
 function pollPad(){if(!open)return;viewControl?.refresh();pauseViewControl?.refresh();const p=Array.from(navigator.getGamepads?.()||[]).find(p=>p?.mapping==='standard');const current=p?.buttons.map(b=>b.pressed)||[];const edge=i=>current[i]&&!previous[i];const choices=[...dialog.querySelectorAll(settingsOpen?'.fracture-settings button,.fracture-settings input,.fracture-settings select':'.fracture-choices button')].filter(node=>!node.disabled);let index=Math.max(0,choices.indexOf(document.activeElement));if(edge(12)||edge(13)){index=(index+(edge(13)?1:choices.length-1))%choices.length;choices[index].focus();}if(edge(0))choices[index].click();if(edge(1)){settingsOpen?showSettings(false):hide();}if(edge(9))hide();previous=current;if(open)padFrame=requestAnimationFrame(pollPad);}
 function show(){if(open||!canOpen())return;viewControl?.refresh();pauseViewControl?.refresh();open=true;document.dispatchEvent(new CustomEvent('pw-hud-overlay'));onPause();if(document.body.classList.contains('xr-mode')||document.body.classList.contains('in-xr'))return;document.exitPointerLock?.();dialog.showModal();previous=Array.from(navigator.getGamepads?.()||[]).find(p=>p?.mapping==='standard')?.buttons.map(b=>b.pressed)||[];padFrame=requestAnimationFrame(pollPad);}
 function hide(resume=true){const wasOpen=open;open=false;cancelAnimationFrame(padFrame);if(dialog.open)dialog.close();if(settingsOpen)showSettings(false);if(resume&&wasOpen)onResume();}
 function status(message){dialog.querySelector('.fracture-status').textContent=message;}
 function enterVR(){show();try{Promise.resolve(onVR(status)).catch(error=>status(error?.message||'Le casque n’a pas pu démarrer.'));}catch(error){status(error.message);}}
 dialog.querySelector('[data-pause-action="settings"]').onclick=()=>showSettings(true);
 dialog.querySelector('[data-pause-action="resume"]').onclick=()=>hide();dialog.querySelector('[data-pause-action="vr"]').onclick=enterVR;
 dialog.querySelector('[data-pause-action="home"]').onclick=()=>{hide(false);onHome();};
 actions.querySelector('[data-session="pause"]').onclick=()=>open?hide():show();actions.querySelector('[data-session="vr"]').onclick=enterVR;
 dialog.addEventListener('cancel',e=>{e.preventDefault();settingsOpen?showSettings(false):hide();});
 const key=e=>{if(!open&&document.querySelector('.pw-actions-open'))return;if(e.code!=='Escape'||!canOpen()||document.querySelector('.pw-prologue')||(!open&&document.querySelector('dialog[open]')))return;e.preventDefault();e.stopImmediatePropagation();if(open&&settingsOpen)showSettings(false);else open?hide():show();};document.addEventListener('keydown',key,true);
 return{dialog,actions,show,hide,status,get isOpen(){return open;},setVisible(value){actions.hidden=!value;},dispose(){document.removeEventListener('keydown',key,true);for(const m of moved.reverse())m.parent.insertBefore(m.node,m.next?.parentNode===m.parent?m.next:null);dialog.remove();actions.remove();}};
}
